-- 615: three new Dreamscapes worlds (Kevin 2026-09-30: "yes, build all three"): Celestial, Overgrown Wonders and
-- Impossible Architecture, the thinnest tile's top-up (2 cards, 206 spots before this). Spots: the paid-for surreal
-- rewrites of each world's source categories (cosmic; overgrown + decay_beauty; impossible_architecture), minus the ones
-- live in Glowing Elements and Impossible Whimsy, curated against the world's concept, topped up with fresh spots and
-- strictly graded (S, then A), near-duplicates dropped. Every spot carries its wonder in the look itself: Flux drops
-- impossible scale and physics (the lesson that retired Land of Giants and Gravity's Off, mig 609).
-- Recipes from generate-full-location-card.js under descriptive names, renamed here; biome fantasy_imagined; biome_config
-- cleared for gen-location-biome.js / gen-location-wardrobe.js, then imagined = true. Like the other Dreamscapes cards:
-- couples_ok = false (solo and scene-only, Kevin) and admin_only until the 1.11.0 go-live. Re-runnable.

UPDATE public.location_cards SET name = 'celestial realm' WHERE name ILIKE 'celestial, a dreamy world%'
  AND NOT EXISTS (SELECT 1 FROM public.location_cards WHERE name = 'celestial realm');
UPDATE public.location_cards SET display_name = 'Celestial', picker_category = 'surreal_dreams', picker_tile = 'surreal_dreams',
  picker_sort_order = 30, biome = 'fantasy_imagined', biome_config = NULL, is_approved = true, admin_only = true,
  content_kind = 'place', couples_ok = false, sub_regions = ARRAY['Planet-rise meadows and gardens', 'Starlit lakes, shores and waterfalls', 'Observatories, domes and glass pavilions', 'Nebula valleys and cloud terraces']::text[], must_include = ARRAY['a ringed planet or a huge moon low over the horizon', 'nebula colours in the sky', 'stars reflected in still water', 'glass observatories, pavilions and telescope terraces', 'flower meadows and gardens under the cosmos', 'dreamy, luminous, romantic']::text[]
WHERE name = 'celestial realm';
ON CONFLICT (location_key, spot_text) DO NOTHING;

UPDATE public.location_cards SET name = 'overgrown wonders' WHERE name ILIKE 'overgrown wonders, a dream world%'
  AND NOT EXISTS (SELECT 1 FROM public.location_cards WHERE name = 'overgrown wonders');
UPDATE public.location_cards SET display_name = 'Overgrown Wonders', picker_category = 'surreal_dreams', picker_tile = 'surreal_dreams',
  picker_sort_order = 40, biome = 'fantasy_imagined', biome_config = NULL, is_approved = true, admin_only = true,
  content_kind = 'place', couples_ok = false, sub_regions = ARRAY['Palaces and ballrooms in bloom', 'Libraries and reading rooms of vines', 'Cathedrals, chapels and cloisters of moss and flowers', 'Stations, theatres and glasshouses gone green']::text[], must_include = ARRAY['flowers and vines covering grand architecture', 'trees growing through floors and roofs', 'sunbeams through broken glass roofs and domes', 'moss, ferns and blossoms on marble and stone', 'lush and peaceful, never grim or rotten']::text[]
WHERE name = 'overgrown wonders';
ON CONFLICT (location_key, spot_text) DO NOTHING;

UPDATE public.location_cards SET name = 'impossible architecture' WHERE name ILIKE 'impossible architecture, a dream world%'
  AND NOT EXISTS (SELECT 1 FROM public.location_cards WHERE name = 'impossible architecture');
UPDATE public.location_cards SET display_name = 'Impossible Architecture', picker_category = 'surreal_dreams', picker_tile = 'surreal_dreams',
  picker_sort_order = 50, biome = 'fantasy_imagined', biome_config = NULL, is_approved = true, admin_only = true,
  content_kind = 'place', couples_ok = false, sub_regions = ARRAY['Endless libraries and archives', 'Staircases and bridges into the clouds', 'Floating towers and sky palaces', 'Doorways and arches that open onto other places']::text[], must_include = ARRAY['architecture as the landscape: stairs, arches, towers, halls', 'clouds and open sky around and through the buildings', 'endless repetition of shelves, arches or stairs', 'serene, elegant and luminous, never ominous']::text[]
WHERE name = 'impossible architecture';
ON CONFLICT (location_key, spot_text) DO NOTHING;

DO $$
BEGIN
  IF (SELECT count(*) FROM public.location_cards WHERE name IN ('celestial realm', 'overgrown wonders', 'impossible architecture') AND picker_tile = 'surreal_dreams') <> 3 THEN
    RAISE EXCEPTION '615: expected the 3 renamed cards (did every recipe save?)';
  END IF;
END $$;
